document.getElementById('open-account')?.addEventListener('click',()=>accountDialog());document.getElementById('welcome-sign-in')?.addEventListener('click',()=>accountDialog());document.getElementById('open-add').addEventListener('click',addDialog);document.getElementById('open-settings').addEventListener('click',settings);
window.addEventListener('hashchange',()=>{if(virtualRoute!==null)return;closeModal();const h=currentHash();if(!h.startsWith('#lesson/'))opened=null;render();window.scrollTo(0,0)});
overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal()});document.addEventListener('keydown',e=>{if(overlay.hidden)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),textarea:not([disabled]),select:not([disabled]),a[href],summary')].filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable[focusable.length-1];if(first&&(!dialog.contains(document.activeElement)||(e.shiftKey&&document.activeElement===first)||(!e.shiftKey&&document.activeElement===last))){e.preventDefault();(e.shiftKey?last:first).focus()}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){searchTerm=e.target.value;filterResults()}});
document.addEventListener('change',async e=>{if(e.target.id==='dark-toggle'){state.theme=e.target.checked?'dark':'light';persist();document.documentElement.classList.toggle('dark',state.theme==='dark')}
 if(e.target.id==='pack-file'&&e.target.files?.[0]){const f=e.target.files[0],target=document.getElementById('pack-input'),generation=profileGeneration;if(f.size>650000){notice('Pack too large (max 650 KB). Import smaller packs.');return}try{const text=await f.text();if(!target?.isConnected||generation!==profileGeneration||document.getElementById('pack-input')!==target)return;target.value=text;previewImport()}catch{notice('Could not read the lesson file. Please select it again.')}}
 if(e.target.id==='backup-file'&&e.target.files?.[0])restoreBackup(e.target.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();signIn(e.target)}if(e.target.id==='quick-form'){e.preventDefault();addQuick(e.target)}if(e.target.id==='quiz-form'){e.preventDefault();gradeQuiz(e.target)}});
document.addEventListener('click',e=>{
 const link=e.target.closest('a[href^="#"]');if(link){e.preventDefault();closeModal();goto(link.getAttribute('href'));return}
 const subject=e.target.closest('[data-welcome-category]');if(subject){selection=subject.dataset.welcomeCategory;libraryTab=activeUser?'Lessons':'Ideas';goto('#discover');return}
 const demo=e.target.closest('[data-demo-account]');if(demo){const account=window.KSAuth?.getDemoAccounts().find(x=>x.id===demo.dataset.demoAccount),form=document.getElementById('login-form');if(account&&form){form.elements.email.value=account.email;form.elements.password.value=account.password;form.querySelector('button[type=submit]').focus()}return}
 const explore=e.target.closest('[data-explore-lesson]');if(explore){openFullLesson(explore.dataset.exploreLesson);return}
 const continueLesson=e.target.closest('[data-sign-in-lesson]');if(continueLesson){openFullLesson(continueLesson.dataset.signInLesson);return}
 const lesson=e.target.closest('[data-lesson]');if(lesson){openFullLesson(lesson.dataset.lesson);return}
 const rev=e.target.closest('[data-review-lesson]');if(rev){opened=rev.dataset.reviewLesson;goto(`#lesson/${opened}/review`);return}
 const idea=e.target.closest('[data-idea]');if(idea){ideaDialog(idea.dataset.idea);return}
 const s=e.target.closest('[data-save]');if(s){toggleSave(s.dataset.save);return}
 const learn=e.target.closest('[data-learn]');if(learn){learnOld(learn.dataset.learn);return}
 const old=e.target.closest('[data-old-review]');if(old){oldReview(old.dataset.oldReview,old.dataset.result);return}
 const stage=e.target.closest('[data-stage]');if(stage){moveStage(stage.dataset.stage);return}
 const cat=e.target.closest('[data-cat]');if(cat){selection=cat.dataset.cat;discover();return}
 const lib=e.target.closest('[data-library]');if(lib){libraryTab=lib.dataset.library;discover();return}
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='browse-quick'){selection='All';libraryTab='Ideas';goto('#discover')}if(action==='sign-in')accountDialog();if(action==='continue-guest')goto('#today');if(action==='browse-lessons'){selection='All';libraryTab='Lessons';goto('#discover')}if(action==='sign-out')signOut();if(action==='close')closeModal();if(action==='add')addDialog();if(action==='copy-prompt')copyPrompt();if(action==='download-prompt')downloadText('Knowledge-Stash-AI-LESSON-PROMPT.txt',aiPrompt());if(action==='choose-pack')document.getElementById('pack-file')?.click();if(action==='preview-pack')previewImport();if(action==='confirm-import')confirmImport();if(action==='export')exportBackup();if(action==='export-pack')exportContentPack();if(action==='choose-backup')document.getElementById('backup-file')?.click();if(action==='reset')reset();if(action==='leave-lesson')leaveLesson();if(action==='retry-quiz')retryQuiz();if(action==='reread')reread();if(action==='clear-answers'){document.getElementById('quiz-form')?.reset();}
});
async function loadPublishedPack(){try{const res=await fetch('./packs/community.json',{cache:'no-cache'});if(!res.ok)throw Error(`HTTP ${res.status}`);const data=validatePack(await res.json());if(data.some(l=>builtin.some(b=>b.id===l.id)))throw Error('Pack conflicts with built-in lesson ID');packLessons=data;render()}catch(e){console.warn('Published pack unavailable; using built-in and local lessons:',e)}}
async function offlineSetup(){if(window.KS_PREVIEW===true)return;if(!('serviceWorker' in navigator)||!['https:','http:'].includes(location.protocol))return;const hadController=!!navigator.serviceWorker.controller;try{const registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});function offer(){if(hadController&&registration.waiting&&!document.querySelector('.update-banner')&&!sessionStorage.getItem('ks-update-hidden')){const box=document.createElement('div');box.className='update-banner';box.innerHTML='<span>New offline app update ready.</span><button class="primary">Update now</button><button class="secondary" aria-label="Later">Later</button>';document.body.appendChild(box);box.querySelector('.primary').onclick=()=>registration.waiting?.postMessage({type:'SKIP_WAITING'});box.querySelector('.secondary').onclick=()=>{sessionStorage.setItem('ks-update-hidden','1');box.remove()};}}
 offer();registration.addEventListener('updatefound',()=>registration.installing?.addEventListener('statechange',offer));let reloaded=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{document.querySelectorAll('.update-banner').forEach(x=>x.remove());if(hadController&&!reloaded){reloaded=true;location.reload()}});
 }catch(e){console.warn('Offline installation unavailable:',e)}}
setRoute(location.hash||(activeUser?'#today':'#welcome'),true);render();loadPublishedPack();if(document.readyState==='complete')offlineSetup();else window.addEventListener('load',offlineSetup);
